// Promo seed: the demo group filmed in the walkthrough video.
//
// Fictional multiplayer games with cover art generated by capture/art.mjs (no
// third-party titles or artwork in the video), a lively group with guests, a live
// session, one waiting for its wrap-up, two months of played history for
// /stats, a find-a-time poll, "I'd play this" marks and a working invite link.
//
// Local promo tooling only — it WIPES app data. Never point it at a real
// database.
//
//   PROMO_TZ=America/Chicago npx tsx promo/walkthrough/seed-promo.ts
//
// PROMO_TZ is the timezone the capture browser uses, so "tonight 8pm" and
// "Saturday 2pm" land where the composer's chips expect them.
import "dotenv/config";

import { neon, neonConfig } from "@neondatabase/serverless";
import { like } from "drizzle-orm";
import { drizzle } from "drizzle-orm/neon-http";

import * as schema from "@/db/schema";
import type { GameMode } from "@/lib/game-modes";
import { sha256Hex } from "@/lib/ids";

import gamesJson from "./games.json";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
	console.error("DATABASE_URL is not set.");
	process.exit(1);
}
if (/neon\.tech/.test(databaseUrl)) {
	console.error("Refusing to run the promo seed against a Neon database — local Postgres only.");
	process.exit(1);
}
if (process.env.NEON_HTTP_PROXY_ENDPOINT) neonConfig.fetchEndpoint = process.env.NEON_HTTP_PROXY_ENDPOINT;
const db = drizzle(neon(databaseUrl), { schema });

const TZ = process.env.PROMO_TZ ?? "UTC";
/** Raw invite token used on camera (stored hashed, like real invites). */
export const PROMO_INVITE_TOKEN = "promo-walkthrough-invite";

// --- ids & time ---------------------------------------------------------------

const pid = (block: string, n: number) => `7a0e${block}-0000-4000-8000-${String(n).padStart(12, "0")}`;
const gameId = (n: number) => pid("0001", n);
const eventId = (n: number) => pid("0002", n);
const pollId = (n: number) => pid("0004", n);
const optionId = (n: number) => pid("0005", n);

const MIN = 60_000;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;
const now = Date.now();
const ago = (ms: number) => new Date(now - ms);

/** Offset (ms) of TZ from UTC at a given instant. */
function tzOffset(at: Date): number {
	const parts = Object.fromEntries(
		new Intl.DateTimeFormat("en-US", { timeZone: TZ, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit" })
			.formatToParts(at)
			.map((p) => [p.type, p.value]),
	);
	const asUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
	return asUtc - at.getTime();
}
/** `days` from today at `hour`:`minute` local time in TZ. */
function localAt(days: number, hour: number, minute = 0): Date {
	const off = tzOffset(new Date(now));
	const local = new Date(now + off);
	const utc = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate() + days, hour, minute) - off;
	return new Date(utc);
}
/** Next Saturday (not today) at `hour` local. */
function nextSaturday(hour: number): Date {
	const local = new Date(now + tzOffset(new Date(now)));
	const days = (6 - local.getUTCDay() + 7) % 7 || 7;
	return localAt(days, hour);
}

// --- people -------------------------------------------------------------------

const alex = "promo-alex";
const brooke = "promo-brooke";
const casey = "promo-casey";
const drew = "promo-drew";
const jordan = "promo-jordan";
const sam = "promo-sam";
const frankie = "promo-frankie";
const riley = "promo-riley";

const users = [
	{ id: alex, name: "Alex Ortega", email: "alex@promo.example", role: "admin", status: "approved" },
	{ id: brooke, name: "Brooke Tran", email: "brooke@promo.example", role: "member", status: "approved" },
	{ id: casey, name: "Casey Nwosu", email: "casey@promo.example", role: "member", status: "approved" },
	{ id: drew, name: "Drew Kaplan", email: "drew@promo.example", role: "member", status: "approved" },
	{ id: jordan, name: "Jordan Lee", email: "jordan@promo.example", role: "member", status: "approved" },
	{ id: sam, name: "Sam Patel", email: "sam@promo.example", role: "member", status: "approved" },
	{ id: frankie, name: "Frankie Moss", email: "frankie@promo.example", role: "guest", status: "approved" },
	{ id: riley, name: "Riley Chen", email: "riley@promo.example", role: "guest", status: "approved" },
] satisfies (typeof schema.user.$inferInsert)[];

// --- games --------------------------------------------------------------------

type Status = (typeof schema.gameStatus.enumValues)[number];
type G = {
	n: number;
	title: string;
	slug: string;
	status: Status;
	by: string;
	genres: string[];
	modes: GameMode[];
	released: string;
	/** Rough main+extra hours, for the library card. */
	hours: number;
	pitch: string;
	/** Generated art: accent colour, base colour, motif (see capture/art.mjs). */
	art: [string, string, string];
};

// Shared with capture/art.mjs, which paints each game's cover and header.
const games = gamesJson as G[];

/** Generated art is served to the capture browser from this (fake) host. */
export const ART_HOST = "art.nextquest.example";
const artUrl = (slug: string, file: string) => `https://${ART_HOST}/${slug}/${file}`;

// --- seeding ------------------------------------------------------------------

async function wipe() {
	// Children before parents; real (non-promo) auth rows are left alone.
	await db.delete(schema.gameInterest);
	await db.delete(schema.inviteRedemptions);
	await db.delete(schema.invites);
	await db.delete(schema.membershipApplications);
	await db.delete(schema.gameRatings);
	await db.delete(schema.gameComments);
	await db.delete(schema.availabilityMarks);
	await db.delete(schema.availabilityResponses);
	await db.delete(schema.availabilityOptions);
	await db.delete(schema.eventDiscordMessages);
	await db.delete(schema.eventAttendance);
	await db.delete(schema.events);
	await db.delete(schema.availabilityPolls);
	await db.delete(schema.gameVoteMilestones);
	await db.delete(schema.votes);
	await db.delete(schema.gameTags);
	await db.delete(schema.tags);
	await db.delete(schema.gameStatusHistory);
	await db.delete(schema.tabletopDetails);
	await db.delete(schema.gameMetadata);
	await db.delete(schema.games);
	await db.delete(schema.session).where(like(schema.session.userId, "promo-%"));
	await db.delete(schema.user).where(like(schema.user.id, "promo-%"));
	await db.delete(schema.user).where(like(schema.user.id, "seed-%"));
}

async function main() {
	await wipe();
	// tutorialSeenAt: the welcome tour must not pop over the footage.
	await db.insert(schema.user).values(users.map((u) => ({ ...u, tutorialSeenAt: new Date() })));
	await db.insert(schema.appSettings).values({ id: 1 }).onConflictDoNothing();

	const history: (typeof schema.gameStatusHistory.$inferInsert)[] = [];
	for (const g of games) {
		const proposedAt = ago((40 + g.n * 3) * DAY);
		await db.insert(schema.games).values({
			id: gameId(g.n),
			title: g.title,
			gameType: "video",
			status: g.status,
			proposedBy: g.by,
			pitch: g.pitch,
			lengthHours: g.hours.toFixed(1),
			startedAt: g.status === "playing" || g.status === "completed" ? ago((20 + g.n) * DAY) : null,
			completedAt: g.status === "completed" ? ago((5 + g.n) * DAY) : null,
			createdAt: proposedAt,
		});
		await db.insert(schema.gameMetadata).values({
			gameId: gameId(g.n),
			source: "manual",
			coverUrl: artUrl(g.slug, "cover.png"),
			headerUrl: artUrl(g.slug, "header.png"),
			genres: g.genres,
			gameModes: g.modes,
			releaseDate: g.released,
			hltbMainExtra: g.hours.toFixed(1),
			fetchedAt: proposedAt,
		});
		history.push({ gameId: gameId(g.n), fromStatus: null, toStatus: "proposed", changedBy: g.by, changedAt: proposedAt });
		history.push({ gameId: gameId(g.n), fromStatus: "proposed", toStatus: "backlog", changedBy: alex, changedAt: new Date(proposedAt.getTime() + DAY) });
		if (g.status === "playing" || g.status === "completed") {
			history.push({ gameId: gameId(g.n), fromStatus: "backlog", toStatus: "playing", changedBy: g.by, changedAt: ago((20 + g.n) * DAY) });
		}
		if (g.status === "completed") {
			history.push({ gameId: gameId(g.n), fromStatus: "playing", toStatus: "completed", changedBy: g.by, changedAt: ago((5 + g.n) * DAY) });
		}
	}
	await db.insert(schema.gameStatusHistory).values(history);

	// "I'd play this"
	const keen: [number, string][] = [
		[17, alex], [17, drew], [17, jordan],
		[18, casey], [18, sam], [18, jordan], [18, drew],
		[19, riley], [19, brooke], [19, casey], [19, sam], [19, alex],
		[20, sam], [20, casey], [20, brooke],
		[1, drew], [1, jordan], [7, brooke],
	];
	await db.insert(schema.gameInterest).values(keen.map(([n, userId]) => ({ gameId: gameId(n), userId })));

	// --- sessions
	type Ev = typeof schema.events.$inferInsert;
	type Att = typeof schema.eventAttendance.$inferInsert;
	const events: Ev[] = [];
	const attendance: Att[] = [];

	// Live right now: Hollow Creek, open, a guest in the lobby.
	events.push({
		id: eventId(1),
		title: "Hollow Creek — quota night",
		gameId: gameId(2),
		scheduledAt: new Date(Math.floor((now - 25 * MIN) / (5 * MIN)) * 5 * MIN),
		durationMinutes: 120,
		visibility: "open",
		capacity: 4,
		venue: "virtual",
		location: "Discord voice",
		joinUrl: "https://discord.gg/example",
		createdBy: casey,
		createdAt: ago(3 * HOUR),
	});
	for (const [u, r] of [[casey, "yes"], [jordan, "yes"], [riley, "yes"]] as const) attendance.push({ eventId: eventId(1), userId: u, rsvp: r });

	// Members-only campaign night on Saturday.
	events.push({
		id: eventId(2),
		title: "Gloomkeep — Act 2",
		gameId: gameId(3),
		scheduledAt: nextSaturday(14),
		durationMinutes: 240,
		visibility: "members",
		capacity: 4,
		venue: "virtual",
		location: "Discord voice",
		notes: "Picking up at the Lantern Inn.",
		progressNote: "Left off at the Lantern Inn after the bridge fight.",
		createdBy: alex,
		createdAt: ago(2 * DAY),
	});
	for (const [u, r] of [[alex, "yes"], [brooke, "yes"], [drew, "yes"], [casey, "maybe"]] as const) attendance.push({ eventId: eventId(2), userId: u, rsvp: r });

	// Ended an hour ago, waiting for its ten-second wrap-up.
	events.push({
		id: eventId(3),
		title: "Core Breakers — deep dive",
		gameId: gameId(4),
		scheduledAt: new Date(Math.floor((now - 4 * HOUR) / (15 * MIN)) * 15 * MIN),
		durationMinutes: 180,
		visibility: "open",
		capacity: 4,
		venue: "virtual",
		location: "Discord voice",
		wrapUpNudgeSentAt: new Date(),
		createdBy: drew,
		createdAt: ago(DAY),
	});
	for (const [u, r] of [[drew, "yes"], [brooke, "yes"], [sam, "yes"], [frankie, "yes"], [jordan, "maybe"]] as const) attendance.push({ eventId: eventId(3), userId: u, rsvp: r });

	// Two months of played nights (for Recently played, /stats, /review).
	const played: { n: number; game: number; title: string; daysAgo: number; hours: number; stars: number; recap: string; who: string[]; open?: boolean }[] = [
		{ n: 10, game: 5, title: "Frostmark — frost giant night", daysAgo: 3, hours: 3, stars: 5, recap: "Giant down. Drew fell off the mountain twice.", who: [sam, drew, brooke, alex], open: true },
		{ n: 11, game: 8, title: "Echo Static", daysAgo: 6, hours: 2, stars: 4, recap: "Banshee. Sam's scream is now the group ringtone.", who: [sam, casey, frankie, jordan], open: true },
		{ n: 12, game: 7, title: "Saltwind", daysAgo: 9, hours: 3, stars: 4, recap: "Sank twice, then stole a fort. Net positive.", who: [jordan, brooke, riley, drew], open: true },
		{ n: 13, game: 1, title: "Starfall Salvage — the big wreck", daysAgo: 12, hours: 3, stars: 5, recap: "Stripped the whole dreadnought. Full extract.", who: [brooke, drew, jordan, alex] },
		{ n: 14, game: 6, title: "Paper Hearts — finale", daysAgo: 15, hours: 3, stars: 5, recap: "Finished it. Nobody is okay about the elephant.", who: [brooke, casey] },
		{ n: 15, game: 9, title: "Mole Party", daysAgo: 18, hours: 2, stars: 3, recap: "Ten players, zero trust.", who: [casey, sam, frankie, riley, jordan, drew], open: true },
		{ n: 16, game: 15, title: "Turbo Kickoff", daysAgo: 22, hours: 2, stars: 4, recap: "Climbed a rank. Lost it the next game.", who: [jordan, drew, sam] },
		{ n: 17, game: 11, title: "Breach Protocol", daysAgo: 25, hours: 2, stars: 3, recap: "We do not talk about the pistol rounds.", who: [jordan, drew, alex, sam, frankie], open: true },
		{ n: 18, game: 14, title: "Critter Colony base build", daysAgo: 29, hours: 4, stars: 4, recap: "The base now has a conveyor belt. Somehow.", who: [sam, casey, alex] },
		{ n: 19, game: 13, title: "Beastward", daysAgo: 35, hours: 3, stars: 5, recap: "Elder drake down on our last life.", who: [alex, drew, brooke] },
		{ n: 20, game: 16, title: "Kitchen Panic 2", daysAgo: 42, hours: 2, stars: 4, recap: "Three stars on 4-4. Friendships intact. Mostly.", who: [brooke, casey, sam, riley], open: true },
		{ n: 21, game: 10, title: "Skyfall Royale", daysAgo: 50, hours: 2, stars: 3, recap: "Third-partied every single game.", who: [drew, jordan, frankie], open: true },
	];
	for (const p of played) {
		const at = localAt(-p.daysAgo, 20);
		events.push({
			id: eventId(p.n),
			title: p.title,
			gameId: gameId(p.game),
			scheduledAt: at,
			durationMinutes: p.hours * 60,
			visibility: p.open ? "open" : "members",
			venue: "virtual",
			location: "Discord voice",
			status: "completed",
			wrappedUpAt: new Date(at.getTime() + (p.hours + 1) * HOUR),
			wrappedUpBy: p.who[0],
			recap: p.recap,
			howItWent: p.stars,
			createdBy: p.who[0],
			createdAt: new Date(at.getTime() - 2 * DAY),
			updatedAt: new Date(at.getTime() + (p.hours + 1) * HOUR),
		});
		for (const u of p.who) attendance.push({ eventId: eventId(p.n), userId: u, rsvp: "yes", attended: true });
	}
	await db.insert(schema.events).values(events);
	await db.insert(schema.eventAttendance).values(attendance);

	// Game ratings for the finished ones.
	await db.insert(schema.gameRatings).values([
		{ gameId: gameId(6), userId: brooke, rating: 5, note: "best co-op ever made" },
		{ gameId: gameId(6), userId: casey, rating: 5, note: null },
		{ gameId: gameId(13), userId: alex, rating: 5, note: "one more hunt" },
		{ gameId: gameId(13), userId: drew, rating: 4, note: null },
		{ gameId: gameId(16), userId: brooke, rating: 4, note: "chaos, lovingly" },
		{ gameId: gameId(16), userId: sam, rating: 4, note: null },
		{ gameId: gameId(9), userId: casey, rating: 3, note: null },
		{ gameId: gameId(9), userId: frankie, rating: 4, note: null },
	]);

	// A find-a-time grid poll for a bigger night.
	await db.insert(schema.availabilityPolls).values({
		id: pollId(1),
		title: "Ashen Crown co-op night — when?",
		kind: "grid",
		gridSessionMinutes: 180,
		gameId: gameId(17),
		createdBy: alex,
		status: "open",
	});
	const day = (d: number) => ({ start: localAt(d, 17), end: localAt(d, 23) });
	const days = [day(3), day(4), day(5)];
	await db.insert(schema.availabilityOptions).values(days.map((d, i) => ({ id: optionId(i + 1), pollId: pollId(1), startsAt: d.start, endsAt: d.end })));
	const span = (d: { start: Date }, from: number, to: number) => ({
		startsAt: new Date(d.start.getTime() + (from - 17) * HOUR),
		endsAt: new Date(d.start.getTime() + (to - 17) * HOUR),
	});
	await db.insert(schema.availabilityMarks).values([
		{ pollId: pollId(1), userId: alex, ...span(days[0], 18, 23) },
		{ pollId: pollId(1), userId: drew, ...span(days[0], 19, 23) },
		{ pollId: pollId(1), userId: jordan, ...span(days[0], 20, 23) },
		{ pollId: pollId(1), userId: brooke, ...span(days[1], 17, 21) },
		{ pollId: pollId(1), userId: alex, ...span(days[1], 19, 22) },
		{ pollId: pollId(1), userId: sam, ...span(days[2], 18, 23) },
		{ pollId: pollId(1), userId: drew, ...span(days[2], 20, 23) },
		{ pollId: pollId(1), userId: jordan, ...span(days[2], 19, 22) },
		{ pollId: pollId(1), userId: casey, ...span(days[0], 20, 22) },
	]);

	// A live invite link (raw token known so the video can open it).
	await db.insert(schema.invites).values({
		tokenHash: await sha256Hex(PROMO_INVITE_TOKEN),
		createdBy: brooke,
		note: "for the Starfall crew",
		maxUses: 5,
		expiresAt: new Date(now + 7 * DAY),
	});

	console.log(`Promo group seeded (TZ ${TZ}): ${users.length} people, ${games.length} games, ${events.length} sessions, 1 poll, 1 invite.`);
}

main().catch((error) => {
	console.error(error);
	process.exit(1);
});
